shellCommand.code:
# Read-only check of top hidden space hogs on Windows 11
$paths = @("$env:LOCALAPPDATA\Temp", "C:\Windows\Temp", "C:\Windows\SoftwareDistribution\Download", "C:\Windows\LiveKernelReports", "$env:LOCALAPPDATA\CrashDumps", "$env:LOCALAPPDATA\NVIDIA\DXCache")
foreach ($p in $paths) {
  if (Test-Path $p) {
    $gb = [math]::Round(((Get-ChildItem $p -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum / 1GB), 2)
    [PSCustomObject]@{ Path = $p; SizeGB = $gb }
  }
}

Get-ChildItem "$env:LOCALAPPDATA" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
  $sum = (Get-ChildItem $_.FullName -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
  [PSCustomObject]@{ Folder = $_.Name; SizeGB = [math]::Round($sum / 1GB, 2) }
} | Sort-Object SizeGB -Descending | Select-Object -First 15
